uses refcount_inc_not_zero() and returns NULL if the refcount is already
zero, which causes ns_get_path_cb() to fail and the caller to return
-ENOENT -- the correct behavior when the netns is being destroyed.

Fixes: 675fc275a3a2d ("bpf: offload: report device information for offloaded programs")
Fixes: 52775b33bb507 ("bpf: offload: report device information about offloaded maps")
Reported-by: Yinhao Hu <dddddd@hust.edu.cn>
Reported-by: Kaiyan Mei <M202472210@hust.edu.cn>
Reviewed-by: Dongliang Mu <dzm91@hust.edu.cn>
Closes: https://lore.kernel.org/bpf/f0aa3678-79c9-47ae-9e8c-02a3d1df160a@hust.edu.cn/
Signed-off-by: Jiayuan Chen <jiayuan.chen@linux.dev>
Acked-by: Daniel Borkmann <daniel@iogearbox.net>
Link: https://lore.kernel.org/r/20260409023733.168050-1-jiayuan.chen@linux.dev
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The bug is a use-after-free in the BPF offload subsystem. When filling info for offloaded BPF programs or maps, the code uses `get_net(dev_net(netdev))` to obtain a reference to the network namespace. However, during netns destruction, the netns refcount may already be zero, and `get_net()` unconditionally increments the refcount on zero, causing a refcount_t addition on 0 that leads to a use-after-free. The fix replaces `get_net()` with `maybe_get_net()` which uses `refcount_inc_not_zero()` to safely handle the case where the netns is being torn down.

Here is the patch:

 static struct ns_common *bpf_prog_offload_info_fill_ns(void *private_data)
 {
 	struct ns_get_path_bpf_prog_args *args = private_data;
 	struct bpf_prog_aux *aux = args->prog->aux;
 	struct ns_common *ns;
 	struct net *net;

 	rtnl_lock();
 	down_read(&bpf_devs_lock);

 	if (aux->offload) {
 		args->info->ifindex = aux->offload->netdev->ifindex;
-		net = dev_net(aux->offload->netdev);
-		get_net(net);
-		ns = &net->ns;
+		net = maybe_get_net(dev_net(aux->offload->netdev));
+		ns = net ? &net->ns : NULL;
 	} else {
 		args->info->ifindex = 0;
 		ns = NULL;
 	}

 	up_read(&bpf_devs_lock);
 	rtnl_unlock();

 	return ns;
 }


 static struct ns_common *bpf_map_offload_info_fill_ns(void *private_data)
 {
 	struct ns_get_path_bpf_map_args *args = private_data;
 	struct ns_common *ns;
 	struct net *net;

 	rtnl_lock();
 	down_read(&bpf_devs_lock);

 	if (args->offmap->netdev) {
 		args->info->ifindex = args->offmap->netdev->ifindex;
-		net = dev_net(args->offmap->netdev);
-		get_net(net);
-		ns = &net->ns;
+		net = maybe_get_net(dev_net(args->offmap->netdev));
+		ns = net ? &net->ns : NULL;
 	} else {
 		args->info->ifindex = 0;
 		ns = NULL;
 	}

 	up_read(&bpf_devs_lock);
 	rtnl_unlock();

 	return ns;
 }



